mapper.select:
SELECT tac.SEQ_NO as seqNo, /** 流水号 **/ tac.FEE_TYPE as feeType, /** 费用品种 **/ tac.BOOKSET_ID as booksetId, /** 账套代码 **/ tac.REGIST_ORG as registOrg, /** 登记托管机构 **/ tac.PAY_CYCLE as payCycle, /** 支付频率 **/ to_char(tac.POSITION_START_DATE,'yyyy-MM-dd') as positionStartDate, /** 计提开始日 **/ to_char(tac.POSITION_END_DATE,'yyyy-MM-dd') as positionEndDate, /** 计提结束日 **/ tac.FEE_AMT_TOTAL as feeAmtTotal /** 区间费用金额 **/ FROM TRD_ACCOUNTMF_CONFIG tac WHERE 1 = 1
AND tac.BOOKSET_ID IN
#{item}
AND tac.POSITION_START_DATE <= to_date(#{positionDateEnd},'yyyy-MM-dd')
AND tac.POSITION_END_DATE >= to_date(#{positionDateBegin},'yyyy-MM-dd')
AND tac.SEQ_NO = #{seqNo}

SELECT bb.BOOKSET_ID as id, bb.BOOKSET_NAME as text, to_char(bbd.BOOKSET_DATE,'yyyy-MM-dd') as object FROM BOK_BOOKSET bb LEFT JOIN BOK_BOOKSET_DATE bbd ON bb.BOOKSET_ID = bbd.BOOKSET_ID
AND bb.BOOKSET_TYPE = #{booksetType}
AND bb.BOOKSET_ID = #{initValue}
AND (bb.BOOKSET_ID like concat('%',concat(#{search},'%')) OR bb.BOOKSET_NAME like concat('%',concat(#{search},'%')))

SELECT
	swbl.SEQ_NO  /** 流程代码 **/
FROM SYS_WFL_BUSINESS_LIST swbl
WHERE swbl.PAGE_ID = #{pageId,jdbcType=VARCHAR}
	AND swbl.PROCESS_STATE = #{processState,jdbcType=VARCHAR}
	AND (swbl.ACTION_TYPE = #{actionType_new,jdbcType=VARCHAR}
	OR swbl.ACTION_TYPE = #{actionType_modify,jdbcType=VARCHAR})
